#!/usr/bin/env python3
"""Resolve and verify GitHub Action pins against their upstream repositories (uses the `gh` CLI, read-only).

  resolve_lock.py generate OUT.tsv owner/repo@vX.Y.Z [...]
      For each exact version tag: read refs/tags/<tag> from the upstream repo, dereference annotated tags to the
      commit, confirm GET repos/<owner>/<repo>/commits/<sha> returns that same SHA, and record which other tags
      (e.g. the floating major `v5`) currently point at the same commit. Unverifiable entries are written with
      verified=no (the checker treats them as absent) and make the command exit 1. SHAs are never guessed.
  resolve_lock.py verify LOCK.tsv
      Re-resolve every row online. Fails if the exact version tag no longer resolves to the pinned SHA, or the
      commit cannot be fetched from the upstream repo. Floating tags moving is reported but is not a failure.
"""
import json, subprocess, sys, datetime

HEADER = ["action", "version", "sha", "also_tags", "tag_object", "verified", "verified_via", "verified_at_utc"]


def gh(path):
    r = subprocess.run(["gh", "api", path], capture_output=True, text=True)
    if r.returncode != 0:
        raise RuntimeError(f"gh api {path}: {r.stderr.strip()[:200]}")
    return json.loads(r.stdout)


def tag_commit(repo, tag):
    ref = gh(f"repos/{repo}/git/ref/tags/{tag}")
    obj = ref["object"]
    kind = obj["type"]
    sha = obj["sha"]
    hops = 0
    while obj["type"] == "tag" and hops < 5:  # annotated tag -> follow to the commit
        obj = gh(f"repos/{repo}/git/tags/{obj['sha']}")["object"]
        sha = obj["sha"]; hops += 1
    if obj["type"] != "commit":
        raise RuntimeError(f"{repo}@{tag} does not resolve to a commit ({obj['type']})")
    return sha, ("annotated" if kind == "tag" else "lightweight")


def commit_exists(repo, sha):
    c = gh(f"repos/{repo}/commits/{sha}")
    return c.get("sha") == sha


def tags_at(repo, sha, major):
    out = []
    try:
        for r in gh(f"repos/{repo}/git/matching-refs/tags/{major}"):
            t = r["ref"].removeprefix("refs/tags/")
            o = r["object"]
            s = o["sha"]
            if o["type"] == "tag":
                s = gh(f"repos/{repo}/git/tags/{s}")["object"]["sha"]
            if s == sha:
                out.append(t)
    except RuntimeError:
        pass
    return out


def generate(out, specs):
    now = datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    rows, bad = [], 0
    for spec in specs:
        repo, _, ver = spec.partition("@")
        try:
            sha, kind = tag_commit(repo, ver)
            ok = commit_exists(repo, sha)
            major = ver.split(".")[0]
            also = [t for t in tags_at(repo, sha, major) if t != ver]
            rows.append([repo, ver, sha, ",".join(sorted(also)) or "-", kind, "yes" if ok else "no",
                         f"gh api repos/{repo}/git/ref/tags/{ver} (+git/tags deref) == repos/{repo}/commits/{sha}", now])
            if not ok:
                bad += 1
        except Exception as e:  # unverifiable: record, never invent
            rows.append([repo, ver, "UNRESOLVED", "-", "-", "no", str(e)[:120], now]); bad += 1
        print("\t".join(rows[-1][:6]))
    with open(out, "w") as f:
        f.write("# Generated by .github/workflows/workflow_lint/resolve_lock.py; verified=yes rows only are trusted.\n")
        f.write("\t".join(HEADER) + "\n")
        for r in sorted(rows):
            f.write("\t".join(r) + "\n")
    return 1 if bad else 0


def verify(lock):
    bad = 0
    header = None
    for line in open(lock):
        if line.startswith("#") or not line.strip():
            continue
        c = line.rstrip("\n").split("\t")
        if header is None:
            header = c; continue
        r = dict(zip(header, c))
        try:
            sha, _ = tag_commit(r["action"], r["version"])
            ok = sha == r["sha"] and commit_exists(r["action"], r["sha"])
            status = "OK" if ok else f"MISMATCH (tag now {sha})"
            moved = []
            for t in [t for t in r["also_tags"].split(",") if t and t != "-"]:
                s2, _ = tag_commit(r["action"], t)
                if s2 != r["sha"]:
                    moved.append(f"{t}->{s2[:12]}")
            print(f"{status}\t{r['action']}@{r['version']}\t{r['sha']}" + (f"\tinfo: floating tag moved {' '.join(moved)}" if moved else ""))
            if not ok or r["verified"] != "yes":
                bad += 1
        except Exception as e:
            print(f"ERROR\t{r['action']}@{r['version']}\t{e}"); bad += 1
    print(f"verify: {'PASS' if not bad else 'FAIL'} ({bad} problems)")
    return 1 if bad else 0


if __name__ == "__main__":
    if len(sys.argv) >= 3 and sys.argv[1] == "generate":
        sys.exit(generate(sys.argv[2], sys.argv[3:]))
    if len(sys.argv) == 3 and sys.argv[1] == "verify":
        sys.exit(verify(sys.argv[2]))
    print(__doc__); sys.exit(2)
